INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 6, 'theory', 'Quiz: cgroups v2');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 6, 0, 'How can you check that a host runs on cgroup v2?', '["cat /proc/version", "mount | grep tmpfs", "systemctl is-system-running", "stat -fc %T /sys/fs/cgroup and get cgroup2fs"]', 3, 'The filesystem type of /sys/fs/cgroup tells the version: cgroup2fs for the second, tmpfs for the first (where separate controller trees are mounted under it).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 6, 1, 'Writing +memory to cgroup.subtree_control of group /a/b is rejected although memory is in its cgroup.controllers. What should you check?', '["The group /a/b has processes of its own", "The size of swap on the host", "Whether memory is enabled in the root once more", "The systemd version"]', 0, 'A non-root group distributes resources to its descendants only if it has no processes of its own. The controller is already available to /a/b since it is in its controllers, so the culprit is the no-internal-process rule.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 6, 2, 'What does the value 200000 100000 in cpu.max mean?', '["A weight of 200 instead of 100", "A quota of 100 ms per 200 ms period, that is half a processor", "The group may use up to two processors", "No more than 200000 processes"]', 2, 'The first number is the quota, the second the period, both in microseconds. The ratio 200000 to 100000 is two processors. The weight is set by a different file, cpu.weight.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 6, 3, 'How does memory.high differ from memory.max?', '["They are equivalent", "high throttles the group and reclaims memory without the OOM killer; max runs the OOM killer in the group when memory cannot be freed", "high is the hard limit and max the soft one", "high applies to swap only"]', 1, 'Above high processes are slowed and made to free memory, but no kill happens. memory.max is the hard border: if memory cannot be freed, the OOM killer runs inside the group.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 6, 4, 'A slice has MemoryMax=2G and a service inside it has MemoryMax=10G. Which limit applies to the service?', '["10G, because it is closer to the service", "12G, the limits add up", "2G, shared with the whole slice", "The service is unlimited"]', 2, 'The tightest limit on the path to the root applies, and the slice''s memory is shared by all its descendants. systemd shows the result in the property EffectiveMemoryMax.');
